def drop(self, gen):
    i, ring = self._drop(gen)

    if self.ring.ngens == 1:
        if self.is_ground:
            return self.coeff(1)
        else:
            raise ValueError("can't drop %s" % gen)
    else:
        poly = ring.zero

        for k, v in self.items():
            if k[i] == 0:
                K = list(k)
                del K[i]
                poly[tuple(K)] = v
            else:
                raise ValueError("can't drop %s" % gen)

        return poly

def _drop_to_ground(self, gen):
    ring = self.ring
    i = ring.index(gen)

    symbols = list(ring.symbols)
    del symbols[i]
    return i, ring.clone(symbols=symbols, domain=ring[i])

def drop_to_ground(self, gen):
    if self.ring.ngens == 1:
        raise ValueError("can't drop only generator to ground")

    i, ring = self._drop_to_ground(gen)
    poly = ring.zero
    gen = ring.domain.gens[0]

    for monom, coeff in self.iterterms():
        mon = monom[:i] + monom[i+1:]
        if not mon in poly:
            poly[mon] = (gen**monom[i]).mul_ground(coeff)
        else:
            poly[mon] += (gen**monom[i]).mul_ground(coeff)

    return poly

def to_dense(self):
    return dmp_from_dict(self, self.ring.ngens-1, self.ring.domain)

def to_dict(self):
    return dict(self)

def str(self, printer, precedence, exp_pattern, mul_symbol):
    if not self:
        return printer._print(self.ring.domain.zero)
    prec_add = precedence["Add"]
    prec_mul = precedence["Mul"]
    prec_atom = precedence["Atom"]
    ring = self.ring
    symbols = ring.symbols
    ngens = ring.ngens
    zm = ring.zero_monom
    sexpvs = []
    for expv, coeff in self.terms():
        positive = ring.domain.is_positive(coeff)
        sign = " + " if positive else " - "
        sexpvs.append(sign)
        if expv == zm:
            scoeff = printer._print(coeff)
            if scoeff.startswith("-"):
                scoeff = scoeff[1:]
        else:
            if not positive:
                coeff = -coeff
            if coeff != 1:
                scoeff = printer.parenthesize(coeff, prec_mul, strict=True)
            else:
                scoeff = ''
        sexpv = []
        for i in range(ngens):
            exp = expv[i]
            if not exp:
                continue
            symbol = printer.parenthesize(symbols[i], prec_atom, strict=True)
            if exp != 1:
                if exp != int(exp) or exp < 0:
                    sexp = printer.parenthesize(exp, prec_atom, strict=False)
                else:
                    sexp = exp
                sexpv.append(exp_pattern % (symbol, sexp))
            else:
                sexpv.append('%s' % symbol)
        if scoeff:
            sexpv = [scoeff] + sexpv
        sexpvs.append(mul_symbol.join(sexpv))
    if sexpvs[0] in [" + ", " - "]:
        head = sexpvs.pop(0)
        if head == " - ":
            sexpvs.insert(0, "-")
    return "".join(sexpvs)

@property
def is_generator(self):
    return self in self.ring._gens_set

@property
def is_ground(self):
    return not self or (len(self) == 1 and self.ring.zero_monom in self)

